func parsePattern(p string) []ptok {
	var toks []ptok
	for len(p) > 0 {
		i := strings.IndexAny(p, ":*")
		if i < 0 {
			toks = append(toks, ptok{0, p})
			break
		}
		if i > 0 {
			toks = append(toks, ptok{0, p[:i]})
		}
		j := strings.IndexByte(p[i:], '/')
		var w string
		if j < 0 {
			w = p[i:]
			p = ""
		} else {
			w = p[i : i+j]
			p = p[i+j:]
		}
		if w[0] == ':' {
			toks = append(toks, ptok{1, w})
		} else {
			toks = append(toks, ptok{2, w})
		}
	}
	return toks
}

func matchToks(toks []ptok, p string) (string, bool) {
	var out strings.Builder
	for k := 0; k < len(toks); k++ {
		t := toks[k]
		switch t.kind {
		case 0:
			if len(p) < len(t.s) || !strings.EqualFold(p[:len(t.s)], t.s) {
				return "", false
			}
			out.WriteString(t.s)
			p = p[len(t.s):]
		case 1:
			end := strings.IndexByte(p, '/')
			var val string
			if end < 0 {
				val = p
				p = ""
			} else {
				val = p[:end]
				p = p[end:]
			}
			out.WriteString(val)
		case 2:
			out.WriteString(p)
			p = ""
		}
	}
	if p != "" {
		return "", false
	}
	return out.String(), true
}

