func parse(route string) (segs [][]part, catchAll string, ok bool) {
	raw := strings.Split(route, "/")
	for i := 1; i < len(raw); i++ {
		s := raw[i]
		if strings.HasPrefix(s, "*") {
			if i != len(raw)-1 {
				return nil, "", false
			}
			catchAll = s[1:]
			if catchAll == "" {
				return nil, "", false
			}
			return segs, catchAll, true
