func wildcardNamesInvalid(path string) (bad []string) {
	// for each ':' or '*', the name runs until '/' or end
	for i := 0; i < len(path); i++ {
		c := path[i]
		if c != ':' && c != '*' {
			continue
		}
		end := i + 1
		for end < len(path) && path[end] != '/' {
			end++
		}
		name := path[i+1 : end]
		if name == "" {
			bad = append(bad, fmt.Sprintf("empty name at %d (%q)", i, path))
		}
		if strings.ContainsAny(name, ":*") {
			bad = append(bad, fmt.Sprintf("multi wildcard at %d (%q)", i, path))
		}
	}
	return
}

